   400→                .validators()
   401→                .get(*index)
   402→                .map(|validator| validator.effective_balance)
   403→        })
   404→        .process_results(|iter| iter.sum::<Gwei>())
   405→        .unwrap_or(0);
   406→
   407→    let count = total_node_balance.saturating_div(config.balance_per_additional_custody_group);
